    "s27_category": "Teil 4: Musterteilekoffer • Systemübersicht",
    "s27_title": "Der Renner Musterteilekoffer (MTK)",
    "s27_subtitle": "Das unverzichtbare Diagnose- und Auswahlinstrument für die Reparaturwerkstatt",
    "s27_bullet_1": "<strong>Direkte Passprüfung:</strong> Musterteile können direkt im Kundeninstrument eingehängt und getestet werden.",
    "s27_bullet_2": "<strong>Umfassendes Fachhandbuch:</strong> Ausführliche Tabellen mit Hebellängen, Winkeln und Kapselabständen.",
    "s27_bullet_3": "<strong>Vermeidung von Fehlbestellungen:</strong> Eindeutige Renner-Artikelnummern für reibungslose Nachbestellung.",
