    "s28_subtitle": "Lückenlose Abdeckung aller Hebelverhältnisse für Flügel aller Epochen",
    "s28_bullet_1": "<strong>15 verschiedene Hebeglied-Varianten:</strong> Jeweils 2 Stück pro Modell als Testmuster im Koffer enthalten.",
    "s28_bullet_2": "<strong>2 Modelle ohne Sattel:</strong> Ermöglichen individuelle Anpassungen bei historischen Sonderkonstruktionen.",
    "s28_bullet_3": "<strong>12 kombinierbare Sättel:</strong> Unterschiedliche Sattelhöhen und Neigungen zur Feinabstimmung der Steighöhe.",
    "s28_bullet_4": "<strong>Sofortige Lieferbarkeit:</strong> Alle 15 Hebeglied-Typen sind bei Renner ab Lager als kompletter Reparatursatz verfügbar.",
