    "s34_c3_title": "5-tägige Ruhephase (Setzprozess)",
    "s34_c1_desc": "Vollautomatische Montagestraße setzt Achsen, Kapseltuch und Schrauben mit digitaler Drehmomentüberwachung.",
    "s34_c2_desc": "Jedes Röllchen und jede Kapselachse wird optisch vermessen. Abweichungen im Zehntelmillimeter-Bereich werden sofort ausgeschleust.",
    "s34_c3_desc": "Alle montierten Hammerstiele lagern zwingend 5 Tage im klimatisierten Baugruppenlager. Dieser Schritt ist fester Bestandteil des Wertstroms und darf nicht unterschritten werden!",
