    "s10_category": "Part 2: Felt Manufacturing • Elastizität",
    "s10_title": "0.56 Shore: Limit of Natural Fulling Hardness",
    "s10_subtitle": "Maximum natural elasticity by eliminating chemical or thermal hardening",
    "s10_b1_badge": "PHYSICAL LIMIT",
    "s10_b2_badge": "FFW WURZEN",
    "s10_c1_title": "Maximum Natural Fulling Hardness",
    "s10_c1_desc": "During fulling, felt sheets are compacted until fibers cannot be compressed further by purely mechanical means. This corresponds to the maximum natural fulling hardness of approx. 0.56 Shore.",
    "s10_caption_1": "Felt sheets at FFW",
