    "s12_title": "Over 30 Felt Sheet Grades in Meuselwitz Climate Storage",
    "s12_subtitle": "Tapered sheet geometry and continuous seasoning control at the Meuselwitz plant",
    "s12_bullet_1": "<strong>Tapered Sheet Geometry:</strong> Felt sheets are engineered in wedge-shaped cross sections – thicker and heavier in the bass, progressively thinner and denser toward the treble.",
    "s12_bullet_2": "<strong>Over 30 Formulations in Stock:</strong> Renner permanently stocks over 30 distinct FFW felt sheet specifications – more than any other manufacturer worldwide.",
    "s12_bullet_3": "<strong>Climate Control & Moth Protection:</strong> Monitored relative humidity and pheromone traps protect natural wool fibers permanently.",
    "s12_bullet_4": "<strong>Tension-Free Seasoning:</strong> Prescribed resting periods prior to strip cutting completely dissipate internal residual stresses.",
    "s12_caption_1": "Felt sheet storage in Meuselwitz: Over 30 sheet varieties permanently available",
