    "s14_category": "Part 2: Felt Manufacturing • Weickert Special",
    "s14_title": "“Weickert Special”: Exclusively for Louis Renner",
    "s14_subtitle": "Highest lanolin retention for unsurpassed voicing stability and tonal response",
    "s14_c1_title": "What makes 'Weickert Special' so unique?",
    "s14_bullet_1": "<strong>Exclusive Formulation:</strong> Manufactured by Filzfabrik Wurzen exclusively for Louis Renner.",
    "s14_bullet_2": "<strong>Higher Wool Grease (Lanolin) Retention:</strong> A gentle proprietary wash preserves more natural lanolin inside the fibers.",
    "s14_bullet_3": "<strong>Reduced Hygroscopic Swelling:</strong> Substantially less sensitive to seasonal swings in atmospheric humidity.",
    "s14_bullet_4": "<strong>Enhanced Clamping Tension:</strong> Exceptional adhesion and dynamic self-tension around the wooden hammer moulding.",
    "s14_bullet_5": "<strong>Enduring Voicing Stability:</strong> The voiced tonal profile remains exceptionally stable over years of concert play.",
    "s14_caption_1": "Weickert Special: Finest wool fiber quality engineered for maximum longevity",
