    "s14_title": "「ヴァイケルト・スペシャル」：レンナー社専用特注フェルト",
    "s14_subtitle": "Höchster Lanolingehalt für unübertroffene Intonationsstabilität und Tonansprache",
    "s14_c1_title": "Was macht „Weickert Special“ so einzigartig?",
    "s14_bullet_1": "<strong>Exklusivrezeptur:</strong> Wird von der Filzfabrik Wurzen ausschließlich für Renner gefertigt.",
    "s14_bullet_2": "<strong>Höherer Wollfettgehalt (Lanolin):</strong> Spezieller Waschprozess belässt mehr natürliches Lanolin in der Faser.",
    "s14_bullet_3": "<strong>Reduziertes Quellverhalten:</strong> Deutlich unempfindlicher gegenüber jahreszeitlichen Luftfeuchteschwankungen.",
    "s14_bullet_4": "<strong>Verbesserte Traktionskräfte:</strong> Außergewöhnliche Adhäsion und Eigenspannung am Holzkern.",
    "s14_bullet_5": "<strong>Dauerhafte Intonationshaltung:</strong> Der einmal intonierte Klangcharakter bleibt über Jahre stabil.",
    "s14_caption_1": "Weickert Special: Feinste Wollfaserqualität mit maximaler Standzeit",
