    "s40_bullet_1": "<strong>1. 打弦距離とキーの深さ：</strong> アクションの打弦距離（46〜48 mm）とキーの深さ（10〜10.5 mm）を正確に測定。",
    "s40_bullet_2": "<strong>2. フレンジレールの基準線：</strong> 弦下面に対するフレンジレールの高さを基準面として設定。",
    "s40_bullet_3": "<strong>3. 基本公式の適用：</strong> 標準的なグランドピアノではボア長＝全長 - 24 mm。",
    "s40_bullet_4": "<strong>4. 数学的検証：</strong> 強度確保のためシャンク突出量が最低3 mmあることを確認。",
