    "s43_category": "第6部：取付・接着技術",
    "s43_title": "固有振動数（ピッチ）テストとシャンクの音響選別",
    "s43_subtitle": "Abklopfen der montierten Stiele: Tiefer Ton im Bass, hohe Resonanz im Diskant",
    "s43_bullet_1": "<strong>Klangprobe durch Antippen:</strong> Jeder Stiel wird sanft angeklopft und seine Eigenresonanz belauscht.",
    "s43_bullet_2": "<strong>Harmonischer Tonverlauf:</strong> Stiele mit tieferer Resonanzfrequenz gehören in den Bass, mittlere in die Mittellage, helle hohe Resonanzen in den Diskant.",
    "s43_bullet_3": "<strong>Homogenes Spielgefühl:</strong> Diese akustische Sortierung verhindert Klangausreißer und ungleiche Energieübertragung.",
