    "s39_c1_title": "Rechtwinkliger Anschlag",
    "s39_c2_title": "Stielüberhang",
    "s39_c1_desc": "Der Hammer muss im Moment des Saitenkontakts exakt im 90°-Winkel auf die Saite treffen. Der Stiel muss ca. 3 mm Überhang haben. Durch die Massenträgheit wird die kinetische Energie gezielt in Richtung Steg geleitet!",
