    "s40_category": "第五部分：参数测绘表与击弦几何学",
    "s40_title": "无旧槌对照样品时逆向推导钻孔深度的四步工程测算法",
    "s40_subtitle": "Die bewährte 4-Schritte-Methode der Renner Academy",
    "s40_c1_title": "Die 4-Schritte-Berechnungsformel:",
    "s40_caption_1": "Messschema zur Ermittlung der Bohrungslänge im Flügel",
    "s40_b1_badge": "公式推导",
    "s40_b2_badge": "几何中心轴",
    "s40_bullet_1": "<strong>1. 开门与下中深度：</strong> 精确测量击弦距离（46–48 mm）和琴键下沉深度（10–10.5 mm）。",
    "s40_bullet_2": "<strong>2. 弦总成基准线：</strong> 以微调总成轨道至琴弦下沿的高度作为基准基面。",
    "s40_bullet_3": "<strong>3. 应用核心公式：</strong> 标准三角琴规格采用 钻孔长度 = 总长 - 24 mm。",
    "s40_bullet_4": "<strong>4. 数学复核校验：</strong> 确保留出至少 3 mm 的柄头余量以保障抗剪强度。",
    "s40_notes": "第 40 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
